def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    MIN_SUPPLY = 15
    MAX_SUPPLY = 25

    supply = day_context['supply']
    hp = my_status['hp']
    budget = my_status['budget']
    no_water_days = my_status['no_water_days']

    if budget <= 0:
        return 0.0

    alive_opponents = []
    for opp_id, opp in opponents_status.items():
        if opp.get('alive'):
            alive_opponents.append(opp)

    if not alive_opponents:
        bid = DAILY_SALARY * 0.22
        if hp <= 2 or no_water_days >= 2:
            bid = DAILY_SALARY * 0.55
        return float(max(0.0, min(budget, bid)))

    highest_prev_bid = 0.0
    cindy_prev_bid = None
    cindy_alive = False
    pressure_count = 0

    for opp_id, opp in opponents_status.items():
        if not opp.get('alive'):
            continue
        prev = opp.get('previous_trace', {})
        prev_bid = 0.0
        if isinstance(prev, dict) and prev.get('bid') is not None:
            prev_bid = prev.get('bid', 0.0)
        if prev_bid > highest_prev_bid:
            highest_prev_bid = prev_bid
        if prev_bid >= DAILY_SALARY * 0.75:
            pressure_count += 1
        if opp_id == 'Cindy':
            cindy_alive = True
            cindy_prev_bid = prev_bid

    scarcity = (supply - MIN_SUPPLY) / float(MAX_SUPPLY - MIN_SUPPLY)
    if scarcity < 0:
        scarcity = 0.0
    if scarcity > 1:
        scarcity = 1.0
    low_supply = 1.0 - scarcity

    urgent = hp <= 2 or no_water_days >= 2
    fragile = hp <= 4 or no_water_days >= 1

    if cindy_alive and cindy_prev_bid is not None:
        anchor = cindy_prev_bid
    else:
        anchor = highest_prev_bid

    if urgent:
        if supply <= 17:
            bid = max(DAILY_SALARY * 0.96, anchor + 2.0)
        else:
            bid = max(DAILY_SALARY * 0.82, anchor * 0.92)
    elif fragile:
        if anchor >= DAILY_SALARY * 1.2:
            bid = DAILY_SALARY * (0.42 + 0.18 * low_supply)
        elif anchor >= DAILY_SALARY * 0.85:
            bid = DAILY_SALARY * (0.48 + 0.18 * low_supply)
        else:
            bid = max(DAILY_SALARY * (0.44 + 0.16 * low_supply), anchor + 1.25)
    else:
        if supply >= 22:
            bid = DAILY_SALARY * 0.18
        elif supply >= 19:
            if anchor >= DAILY_SALARY * 1.0:
                bid = DAILY_SALARY * 0.24
            else:
                bid = DAILY_SALARY * 0.32
        else:
            if anchor >= DAILY_SALARY * 1.2:
                bid = DAILY_SALARY * 0.28
            elif pressure_count >= 2:
                bid = DAILY_SALARY * 0.38
            else:
                bid = max(DAILY_SALARY * 0.36, anchor + 1.0)

    if budget < DAILY_SALARY * 0.8 and not urgent:
        bid = min(bid, budget * 0.55)
    elif budget < DAILY_SALARY * 1.5 and fragile:
        bid = min(bid, budget * 0.72)

    if urgent:
        bid = max(bid, min(budget, DAILY_SALARY * 0.75))

    bid = max(0.0, min(budget, bid))
    return float(bid)

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 9
    DAILY_SALARY = 90
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = float(day_context['supply'])
    day = int(day_context['day'])

    # Identify alive opponents and use only yesterday's previous_trace
    alive = []
    for opp_id, opp in opponents_status.items():
        if opp.get('alive', False):
            prev = opp.get('previous_trace', {}) or {}
            alive.append((opp_id, opp, prev))

    if not alive:
        return float(min(my_status['budget'], DAILY_SALARY * 0.4))

    # Collect yesterday bids and pressure signals
    yesterday_bids = []
    for _, opp, prev in alive:
        b = prev.get('bid', None)
        if b is not None:
            try:
                yesterday_bids.append(float(b))
            except Exception:
                pass

    # If Cindy is alive, her yesterday high average suggests she will continue aggressive bidding.
    # We'll cap our bid to avoid burning budget while still contesting.
    cindy = opponents_status.get('Cindy', None)
    cindy_prev = (cindy.get('previous_trace', {}) if cindy else {})
    cindy_bid = cindy_prev.get('bid', None)

    # Base bid determined by supply and our HP
    # Higher supply -> we can bid less to still secure enough water.
    # Lower supply -> bid more to avoid losing to Cindy.
    supply_frac = (supply - MIN_SUPPLY) / (MAX_SUPPLY - MIN_SUPPLY)
    if supply_frac < 0.0:
        supply_frac = 0.0
    if supply_frac > 1.0:
        supply_frac = 1.0

    hp = float(my_status['hp'])
    budget = float(my_status['budget'])

    # Target contest level: start from a moderate fraction of salary.
    # If HP is low, increase.
    if hp <= 2.0:
        base = DAILY_SALARY * 0.85
    elif hp <= 4.0:
        base = DAILY_SALARY * 0.70
    else:
        base = DAILY_SALARY * 0.55

    # Adjust for supply: lower supply increases bid
    base *= (0.85 + (1.0 - supply_frac) * 0.35)  # range roughly 0.85..1.2

    # If Cindy was bidding high yesterday, slightly increase our bid to stay competitive.
    if cindy is not None and cindy.get('alive', False):
        if cindy_bid is not None:
            try:
                cindy_bid_f = float(cindy_bid)
            except Exception:
                cindy_bid_f = None
            if cindy_bid_f is not None:
                # If Cindy bid extremely high yesterday, we don't match fully; just nudge above a likely threshold.
                if cindy_bid_f >= DAILY_SALARY * 0.85:
                    base = max(base, DAILY_SALARY * 0.62)
                elif cindy_bid_f >= DAILY_SALARY * 0.6:
                    base = max(base, DAILY_SALARY * 0.56)

    # If there were any very high bids yesterday, raise a bit; otherwise keep moderate.
    if yesterday_bids:
        highest_prev = max(yesterday_bids)
        if highest_prev >= DAILY_SALARY * 0.9:
            base *= 1.08
        elif highest_prev >= DAILY_SALARY * 0.7:
            base *= 1.04

    # Ensure we don't overbid beyond budget.
    # Also, avoid bidding more than what would be needed to secure water with some margin.
    # Convert supply to a rough number of water units we can potentially get.
    # If supply is near our requirement, contest more.
    if supply <= WATER_REQ + 1.0:
        base *= 1.12
    elif supply >= WATER_REQ + 6.0:
        base *= 0.92

    bid = float(min(budget, base))

    # Safety: if budget is tiny, bid what's left.
    if bid < 0.0:
        bid = 0.0

    return bid

